using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 renamed "Discriminator" to "$type".
            // Existing documents use "Discriminator", so preserve the old property name.
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 2: EF 9 uses only the raw key for "id" (e.g. "1").
            // Existing documents have id = "Blog|1", so preserve the old format.
            entity.HasIdProperty(b => b.Id, useDiscriminatorInId: true);

            // Breaking change 3: Cosmos DB does not support indexes defined via EF.
            // HasIndex() now throws at model validation in EF 9. Remove it.
            // (HasIndex call removed)
        });
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

